import {
    Table,
    StringColumn,
    ConditionsColumn,
    ReferenceColumn,
    ScriptColumn,
    BooleanColumn,
    ListColumn,
    RadioColumn,
    ChoiceColumn,
} from '../../db'

export const sys_security_acl = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    extensible: true,
    label: 'Access Control',
    name: 'sys_security_acl',
    schema: {
        name: StringColumn({ mandatory: true }),
        condition: ConditionsColumn({
            attributes: {
                extended_operators: 'IN_SESSION',
                show_condition_count: true,
            },
            dependent: 'name',
            label: 'Condition',
        }),
        applies_to: ConditionsColumn({
            attributes: {
                show_condition_count: true,
            },
            dependent: 'name',
            label: [
                {
                    hint: 'Applies To defines data to which the ACL will be applied',
                    label: 'Applies To',
                    plural: 'Applies Tos',
                },
            ],
        }),
        operation: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_sequence: 'order^name',
            },
            default: 'create',
            dropdown: 'dropdown_without_none',
            label: 'Operation',
            mandatory: true,
            referenceTable: 'sys_security_operation',
        }),
        description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Description',
            maxLength: 4000,
        }),
        script: ScriptColumn({}),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        advanced: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show options to control this ACL with references and script. Only use a script when roles and conditions are not sufficient for this ACL.',
                    label: 'Advanced',
                    plural: 'Advanced',
                },
            ],
        }),
        admin_overrides: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Users with admin role override this rule',
                    label: 'Admin overrides',
                    plural: 'Admin overrides',
                },
            ],
        }),
        controlled_by_refs: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            cascadeRule: 'none',
            label: [
                {
                    hint: "[Record-level ACLs only] Access to the record is controlled by one or more of its reference fields. Remove any fields from this ACL's name to utilize this feature.",
                    label: 'Controlled by References',
                    plural: 'Controlled by References',
                },
            ],
            referenceTable: 'sys_dictionary',
            referenceKey: 'element',
            referenceQual: 'javascript:new global.ReferenceQualifierHelper().getQueryConditionForRefs(current.name)',
        }),
        local_or_existing: RadioColumn({
            default: 'Existing',
            choices: {
                Existing: {
                    label: 'Existing',
                },
                Local: {
                    label: 'Local',
                },
            },
            label: 'Local or Existing',
        }),
        security_attribute: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Security Attribute',
            referenceTable: 'sys_security_attribute',
            referenceQual: 'is_localized=false^type=compound^active=true',
            useReferenceQualifier: 'simple',
        }),
        decision_type: ChoiceColumn({
            default: 'allow',
            choices: {
                allow: {
                    label: 'Allow If',
                    sequence: 1,
                },
                deny: {
                    label: 'Deny Unless',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Decision Type defines whether the ACL should allow access or deny access',
                    label: 'Decision Type',
                    plural: 'Decision Types',
                },
            ],
        }),
        type: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'record',
            dropdown: 'dropdown_without_none',
            label: 'Type',
            mandatory: true,
            referenceTable: 'sys_security_type',
        }),
    },
    textIndex: true,
})
